/**
 * The MiSArch packet's metric docs (docs `metrics`): how every objective, constraint and metric the explorer shows is
 * computed — the data of every `?` popover (web/src/help/MetricHelp.tsx, keyed by MetricDoc.key). One
 * registry, keyed by the keys of the run contract (Run.objectives / constraints / metrics) plus the design table's and
 * the performance panel's own figures. Every text is derived from the code that computes the value
 * (core/mdeo/transform/metrics.fn over the SimOxide simulations of a design, the plugin's pcmEvaluate in
 * ../palladio-sim-service (API-pcmEvaluate.md), cases/misarch/explorer-packet/export-run.ts, core/explorer/server/simulator.ts)
 * and cites it (docs/quality.md describes the same functions). tests/metric-docs.test.ts checks that every key of the exported runs has an entry.
 *
 * Text conventions: `code` in backticks; formulas are TeX (KaTeX).
 */
import type { MetricDoc, Ref } from '../../../../core/explorer/web/src/lib/metricDocs';


type Lit = Omit<Ref, 'relation' | 'note'>;
/** the verified works (Crossref metadata for the DOIs, publisher pages for the rest; checked 2026-10-21) */
